internal inline fun <T> required(present: Boolean, field: String, value: () -> T): T { require(present) { "$field is required" }; return value() }
internal fun <T> strictSet(values: List<T>): Set<T> = LinkedHashSet(values).also { require(it.size == values.size) { "set contains duplicate entries" } }
internal fun <K,V> strictMap(values: List<Pair<K,V>>): Map<K,V> = linkedMapOf<K,V>().apply { values.forEach { (key,value) -> require(!containsKey(key)) { "map contains duplicate key: $key" }; put(key,value) } }
